"""Evaluation helpers.

Every function takes the anomaly scores first and the labels second, so labels
are only ever consumed *after* the model has produced predictions (R9, R10).
"""

from __future__ import annotations

from typing import Dict, Iterable, Sequence

import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score


def roc_auc(scores: Sequence[float], y: Sequence[int]) -> float:
    """AUC-ROC (R9)."""
    return float(roc_auc_score(np.asarray(y).astype(int), np.asarray(scores, dtype=float)))


def auc_pr(scores: Sequence[float], y: Sequence[int]) -> float:
    """AUC-PR via the step-function (average precision) definition.

    This is the convention used by ADBench / PyOD and is the primary AUC-PR
    number reported here.
    """
    return float(
        average_precision_score(np.asarray(y).astype(int), np.asarray(scores, dtype=float))
    )


def auc_pr_trapezoid(scores: Sequence[float], y: Sequence[int]) -> float:
    """AUC-PR via the trapezoidal rule over the precision-recall curve."""
    y = np.asarray(y).astype(int)
    s = np.asarray(scores, dtype=float)
    precision, recall, _ = precision_recall_curve(y, s)
    return float(np.trapezoid(precision, recall))


def evaluate(scores: Sequence[float], y: Sequence[int]) -> Dict[str, float]:
    return {
        "auc_roc": roc_auc(scores, y),
        "auc_pr": auc_pr(scores, y),
        "auc_pr_trapezoid": auc_pr_trapezoid(scores, y),
    }


def summarize(values: Iterable[float]) -> Dict[str, float]:
    """mean / std / min / max over the repeated runs (R8)."""
    v = np.asarray(list(values), dtype=float)
    if v.size == 0:
        return {"mean": float("nan"), "std": float("nan"), "min": float("nan"), "max": float("nan")}
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
    }

